function t(k){return (translations[currentLanguage]&&translations[currentLanguage][k])||k;}
function money(v){return Number(v||0).toFixed(2)+" DH";}
function escapeHTML(v){return String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;");}
function escapeAttr(v){return escapeHTML(v);}
function localDateISO(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,"0"),dd=String(d.getDate()).padStart(2,"0");return`${y}-${m}-${dd}`;}
function downloadFile(n,c,t){const b=new Blob([c],{type:t});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download=n;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(u);}
function csvEscape(v){const s=String(v??"");return/[;"\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;}
function icon(name,size){size=size||18;const I={plus:'<line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>',minus:'<line x1="5" y1="12" x2="19" y2="12"/>',trash:'<polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"/>',edit:'<path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/>',print:'<polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/>',money:'<path d="M21 12V7H5a2 2 0 0 1 0-4h14v4"/><path d="M3 5v14a2 2 0 0 0 2 2h16v-5"/><path d="M18 12a2 2 0 0 0 0 4h4v-4z"/>',camera:'<path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/>',cart:'<circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/>',check:'<polyline points="20 6 9 17 4 12"/>',alert:'<path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/>',info:'<circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/>',package:'<path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><polyline points="3.27 6.96 12 12.01 20.73 6.96"/><line x1="12" y1="22.08" x2="12" y2="12"/>'};return'<svg class="icon" width="'+size+'" height="'+size+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+(I[name]||'')+'</svg>';}

function toast(msg,type){type=type||'info';const s=document.getElementById("toastStack");if(!s)return;const el=document.createElement("div");el.className="toast "+type;const i=type==='success'?'check':type==='error'?'alert':type==='warn'?'alert':'info';el.innerHTML='<div class="toast-icon">'+icon(i,16)+'</div><div>'+escapeHTML(msg)+'</div>';s.appendChild(el);setTimeout(()=>{el.classList.add("leaving");setTimeout(()=>el.remove(),200);},2800);}

function saveDB(){localStorage.setItem(DB_KEY,JSON.stringify(db));if(window.fsSaveDB)window.fsSaveDB(db);}
function createDefaultDB(){db.products=[];db.cashiers=[{id:"C1",name:"Caissière 1"},{id:"C2",name:"Caissière 2"}];db.clients=[];db.sales=[];db.suppliers=[];db.purchases=[];db.returns=[];db.settings={storeName:"Zarouali POS",currency:"DH"};saveDB();}

function loadTheme(){const s=localStorage.getItem(THEME_KEY);const h=document.documentElement;const tg=document.getElementById("themeToggle");if(s==='dark'){h.setAttribute('data-theme','dark');if(tg)tg.checked=false;}else{h.removeAttribute('data-theme');if(tg)tg.checked=true;}}
function toggleTheme(c){const h=document.documentElement;if(c){h.removeAttribute('data-theme');localStorage.setItem(THEME_KEY,'light');}else{h.setAttribute('data-theme','dark');localStorage.setItem(THEME_KEY,'dark');}}

function normalizeProductImage(img){let v=String(img||"").trim();if(!v)return"";if(/^(https?:|data:|blob:)/i.test(v))return v;v=v.replace(/^["']+|["']+$/g,"").trim();v=v.replace(/\\/g,"/").replace(/^\.\/+/,"").replace(/^images\/+/,"");return v?IMAGE_BASE_URL+v:"";}
function normalizeCatalogProduct(p){return{...p,id:String(p.id||"").trim(),name:String(p.name||"").trim(),category:String(p.category||"Épicerie").trim(),barcode:String(p.barcode||"").trim(),price:Number(p.price||0),purchasePrice:Number(p.purchasePrice||0),stock:Number.isFinite(Number(p.stock))?Number(p.stock):50,minStock:Number.isFinite(Number(p.minStock))?Number(p.minStock):5,image:normalizeProductImage(p.image),expirationDate:String(p.expirationDate||"").trim()};}

function parseCSVLine(line,sep){const r=[];let c="",ins=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(ins&&line[i+1]==='"'){c+='"';i++;}else ins=!ins;}else if(ch===sep&&!ins){r.push(c);c="";}else c+=ch;}r.push(c);return r;}
function parseCSVToProducts(csv){const lines=csv.split("\n").filter(l=>l.trim());if(lines.length<2)return[];const sep=lines[0].includes(';')?';':',';const h=parseCSVLine(lines[0],sep);const idx={};['id','name','category','barcode','price','purchasePrice','stock','minStock','image','expirationDate'].forEach(k=>{idx[k]=h.indexOf(k);});const out=[];for(let i=1;i<lines.length;i++){const cols=parseCSVLine(lines[i],sep);if(cols.length<2)continue;const id=(idx.id>=0&&cols[idx.id])?cols[idx.id].trim():"P"+String(i).padStart(3,"0");const name=(idx.name>=0&&cols[idx.name])?cols[idx.name].trim():"Produit "+i;const category=(idx.category>=0&&cols[idx.category])?cols[idx.category].trim():"Autre";const barcode=(idx.barcode>=0&&cols[idx.barcode])?cols[idx.barcode].trim():"";const price=(idx.price>=0&&cols[idx.price]?.trim())?(parseFloat(cols[idx.price].replace(",","."))||0):0;const purchasePrice=(idx.purchasePrice>=0&&cols[idx.purchasePrice]?.trim())?(parseFloat(cols[idx.purchasePrice].replace(",","."))||0):0;const stock=(idx.stock>=0&&cols[idx.stock])?parseInt(cols[idx.stock])||50:50;const minStock=(idx.minStock>=0&&cols[idx.minStock])?parseInt(cols[idx.minStock])||5:5;const image=(idx.image>=0&&cols[idx.image])?cols[idx.image].trim():"";const expirationDate=(idx.expirationDate>=0&&cols[idx.expirationDate])?cols[idx.expirationDate].trim():"";if(id&&name)out.push({id,name,category,barcode,price,purchasePrice,stock,minStock,image,expirationDate});}return out;}

function setLanguage(lang){if(!translations[lang])return;currentLanguage=lang;localStorage.setItem(LANG_KEY,lang);document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.documentElement.lang=lang;const f=document.getElementById('langFr'),a=document.getElementById('langAr');if(f)f.checked=(lang==='fr');if(a)a.checked=(lang==='ar');renderMenu();renderMainContent();renderAll();}

