        <div id="creditBarContainer" class="credit-bar-container"><div class="credit-bar-label"><span>Dette</span><span id="creditBarText">0 DH</span></div><div class="credit-bar-track"><div id="creditBarFill" class="credit-bar-fill" style="width:0%"></div></div></div>
