/* ==================== Returns ==================== */
const Returns={currentSale:null,selections:{},open(saleId){const sale=db.sales.find(s=>s.id===saleId);if(!sale){toast('Introuvable','error');return;}this.currentSale=sale;this.selections={};const cashier=db.cashiers.find(c=>c.id===sale.cashierId);const client=db.clients.find(c=>c.id===sale.clientId);document.getElementById('returnSaleInfo').innerHTML='<div style="display:grid;grid-template-columns:1fr auto;gap:12px"><div><div class="eyebrow">Ticket</div><div style="font-family:var(--font-mono);font-weight:800;font-size:16px;margin-top:2px">'+escapeHTML(sale.id)+'</div><div style="font-size:12px;color:var(--text-muted);margin-top:4px">'+new Date(sale.date).toLocaleString('fr-FR')+' · '+(cashier?escapeHTML(cashier.name):'—')+'</div></div><div style="text-align:end"><div class="eyebrow">Total</div><div style="font-size:20px;font-weight:800;font-family:var(--font-mono)">'+money(sale.total)+'</div></div></div>';const list=document.getElementById('returnItemsList');list.innerHTML=sale.items.map((it,i)=>'<div class="return-item-row"><input type="checkbox" class="return-item-check" data-idx="'+i+'" onchange="Returns.toggle('+i+',this.checked)"><div><div class="return-item-name">'+escapeHTML(it.name)+'</div><div class="return-item-meta">'+money(it.price)+' × '+it.qty+'</div></div><input type="number" class="return-qty-input" min="0" max="'+it.qty+'" value="'+it.qty+'" data-idx="'+i+'" onchange="Returns.setQty('+i+',this.value)" disabled><div class="return-item-total" data-total-idx="'+i+'">0.00 DH</div></div>').join('');document.getElementById('returnReason').value='defect';document.getElementById('returnRefundType').value=client&&(client.debt||0)>0?'credit':'cash';document.getElementById('returnNote').value='';this.updateTotal();document.getElementById('returnModal').classList.add('show');},toggle(idx,checked){const it=this.currentSale.items[idx];if(!it)return;const input=document.querySelector('.return-qty-input[data-idx="'+idx+'"]');if(checked){this.selections[idx]=parseInt(input.value)||it.qty;input.disabled=false;}else{delete this.selections[idx];input.disabled=true;}this.updateTotal();},setQty(idx,value){const it=this.currentSale.items[idx];if(!it)return;let q=parseInt(value)||0;if(q<0)q=0;if(q>it.qty)q=it.qty;this.selections[idx]=q;const input=document.querySelector('.return-qty-input[data-idx="'+idx+'"]');if(input)input.value=q;const cb=document.querySelector('.return-item-check[data-idx="'+idx+'"]');if(cb)cb.checked=q>0;this.updateTotal();},updateTotal(){let total=0;Object.entries(this.selections).forEach(([idx,qty])=>{const it=this.currentSale.items[parseInt(idx)];if(it&&qty>0)total+=it.price*qty;});document.getElementById('returnTotal').textContent=money(total);},process(){if(!this.currentSale)return;const items=[];Object.entries(this.selections).forEach(([idx,qty])=>{if(qty>0){const it=this.currentSale.items[parseInt(idx)];items.push({id:it.id,name:it.name,price:it.price,qty});}});if(!items.length){toast('Aucun article','warn');return;}const total=items.reduce((s,i)=>s+i.price*i.qty,0);const refundType=document.getElementById('returnRefundType').value;const ret={id:'R'+Date.now().toString(36).toUpperCase(),date:new Date().toISOString(),saleId:this.currentSale.id,clientId:this.currentSale.clientId,items,total,refundType};for(const it of items){const p=db.products.find(x=>x.id===it.id);if(p)p.stock+=it.qty;}if(refundType==='credit'&&ret.clientId){const c=db.clients.find(x=>x.id===ret.clientId);if(c)c.debt=Math.max(0,(c.debt||0)-total);}if(!db.returns)db.returns=[];db.returns.push(ret);saveDB();closeModal('returnModal');renderAll();toast('Retour: '+money(total),'success');AuditLog.log('return.create','Retour '+ret.id,'');}};

/* ==================== CommandPalette ==================== */
const CommandPalette={items:[],filtered:[],selected:0,isOpen:false,init(){document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();this.toggle();}if(!this.isOpen)return;if(e.key==='Escape'){e.preventDefault();this.close();}if(e.key==='ArrowDown'){e.preventDefault();this.move(1);}if(e.key==='ArrowUp'){e.preventDefault();this.move(-1);}if(e.key==='Enter'){e.preventDefault();this.execute();}});const input=document.getElementById('cmdInput');if(input)input.addEventListener('input',()=>this.search(input.value));const m=document.getElementById('cmdPaletteModal');if(m)m.addEventListener('click',e=>{if(e.target===m)this.close();});},build(){const items=[];MENU_SECTIONS.forEach(section=>{section.items.forEach(p=>{items.push({type:'page',section:section.title,title:t(p.label),sub:'',icon:p.icon,action:()=>{if(p.protected){const btn=[...document.querySelectorAll('.menu-item')].find(b=>b.textContent.includes(t(p.label).split(' ')[0]));protectedPage(p.id,btn);}else{goPage(p.id,document.querySelector('.menu-item'));}}});});});[{label:'Nouvelle vente',icon:'plus',action:()=>{cart=[];renderCart();}},{label:'Scanner',icon:'camera',action:()=>openScanner()},{label:'Historique scans',icon:'history',action:()=>ScanHistory.open()},{label:'Valider vente',icon:'check',action:()=>completeSale()},{label:'Vider panier',icon:'trash',action:()=>clearCart()},{label:'Ventes en attente',icon:'package',action:()=>ParkedSales.openPanel()},{label:'Rapports',icon:'chart',action:()=>AdvancedReports.open()},{label:'Étiquettes',icon:'tag',action:()=>LabelGenerator.open()},{label:'Audit',icon:'history',action:()=>AuditLog.open()},{label:'Alertes',icon:'alert',action:()=>StockAlerts.openPanel()}].forEach(a=>items.push({type:'action',section:'Actions',title:a.label,sub:'',icon:a.icon,action:a.action}));db.products.slice(0,30).forEach(p=>items.push({type:'product',section:'Produits',title:p.name,sub:money(p.price)+' · Stock: '+p.stock,icon:'package',action:()=>{addToCart(p.id);toast('✓ '+p.name,'success');}}));db.clients.slice(0,20).forEach(c=>items.push({type:'client',section:'Clients',title:c.name,sub:(c.phone||'')+((c.debt||0)>0?' · Dette: '+money(c.debt):''),icon:'users',action:()=>{const sel=document.getElementById('saleClient');if(sel){sel.value=c.id;onClientChange();}goPage('sale',document.querySelector('.menu-item'));}}));return items;},ICONS:MENU_ICONS,svg(name,size){size=size||16;return'<svg width="'+size+'" height="'+size+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+(this.ICONS[name]||'')+'</svg>';},open(){this.items=this.build();this.filtered=this.items.slice(0,40);this.selected=0;this.isOpen=true;const m=document.getElementById('cmdPaletteModal');const i=document.getElementById('cmdInput');m.classList.add('show');if(i){i.value='';setTimeout(()=>i.focus(),100);}this.render();},close(){this.isOpen=false;document.getElementById('cmdPaletteModal').classList.remove('show');},toggle(){this.isOpen?this.close():this.open();},search(q){q=String(q||'').toLowerCase().trim();if(!q){this.filtered=this.items.slice(0,40);this.selected=0;this.render();return;}const terms=q.split(/\s+/);this.filtered=this.items.filter(it=>{const text=(it.title+' '+(it.sub||'')).toLowerCase();return terms.every(t=>text.includes(t));}).slice(0,50);this.selected=0;this.render();},move(d){const n=this.filtered.length;if(!n)return;this.selected=(this.selected+d+n)%n;this.render();},execute(){const item=this.filtered[this.selected];if(!item)return;this.close();setTimeout(()=>{try{item.action();}catch(e){console.warn(e);}},100);},render(){const box=document.getElementById('cmdResults');if(!box)return;if(!this.filtered.length){box.innerHTML='<div class="cmd-empty">Aucun résultat</div>';return;}const groups={};this.filtered.forEach(it=>{if(!groups[it.section])groups[it.section]=[];groups[it.section].push(it);});let html='';let idx=0;for(const[section,items]of Object.entries(groups)){html+='<div class="cmd-section">'+section+'</div>';for(const it of items){const isSel=idx===this.selected;html+='<div class="cmd-item '+(isSel?'selected':'')+'" data-idx="'+idx+'" onmouseenter="CommandPalette.select('+idx+')" onclick="CommandPalette.pick('+idx+')"><div class="cmd-item-icon">'+this.svg(it.icon,16)+'</div><div class="cmd-item-body"><div class="cmd-item-title">'+escapeHTML(it.title)+'</div>'+(it.sub?'<div class="cmd-item-sub">'+escapeHTML(it.sub)+'</div>':'')+'</div></div>';idx++;}}box.innerHTML=html;const sel=box.querySelector('.cmd-item.selected');if(sel)sel.scrollIntoView({block:'nearest'});},select(i){this.selected=i;this.render();},pick(i){this.selected=i;this.execute();}};

/* ==================== CustomerDisplay ==================== */
const CustomerDisplay={win:null,channel:null,init(){try{this.channel=new BroadcastChannel('zarouali_customer_display');}catch(e){}},open(){if(this.win&&!this.win.closed){this.win.focus();return;}this.win=window.open('','CustomerDisplay','width=900,height=650');if(!this.win){toast('Popup bloqué','warn');return;}const store=getStoreInfo();this.win.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Client</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:Inter,sans-serif;background:linear-gradient(135deg,#0f172a,#1e293b);color:#fff;min-height:100vh;display:flex;flex-direction:column}.h{padding:22px 32px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid rgba(255,255,255,.08)}.n{font-size:24px;font-weight:800}.c{font-family:monospace;font-size:34px;font-weight:700;color:#86b948}.items{flex:1;overflow-y:auto;padding:26px 32px}.item{display:grid;grid-template-columns:1fr auto auto;gap:24px;padding:14px 0;border-bottom:1px solid rgba(255,255,255,.06);font-size:20px;align-items:center}.nm{font-weight:600}.q{color:rgba(255,255,255,.5);font-family:monospace}.p{font-family:monospace;font-weight:700;color:#86b948;min-width:130px;text-align:right}.f{padding:28px 32px;background:rgba(0,0,0,.35);border-top:1px solid rgba(255,255,255,.1);display:flex;justify-content:space-between;align-items:center}.lbl{font-size:14px;text-transform:uppercase;letter-spacing:.12em;opacity:.6;margin-bottom:8px}.t{font-size:64px;font-weight:900;font-family:monospace;color:#86b948}.emp{text-align:center;padding:100px 20px;opacity:.4}</style></head><body><div class="h"><div class="n">'+escapeHTML(store.name||'Zarouali POS')+'</div><div class="c" id="clk">--:--:--</div></div><div class="items" id="it"><div class="emp"><h2>Bienvenue</h2><p>En attente...</p></div></div><div class="f"><div><div class="lbl">Total</div></div><div class="t" id="tot">0.00 DH</div></div><script>const ch=new BroadcastChannel("zarouali_customer_display");ch.onmessage=e=>{if(e.data&&e.data.type==="update")r(e.data.payload);};function r(d){const i=document.getElementById("it"),t=document.getElementById("tot");if(!d.items||!d.items.length){i.innerHTML=\'<div class="emp"><h2>Bienvenue</h2><p>En attente...</p></div>\';t.textContent="0.00 DH";return;}i.innerHTML=d.items.map(x=>\'<div class="item"><div class="nm">\'+x.name+\'</div><div class="q">× \'+x.qty+\'</div><div class="p">\'+(x.price*x.qty).toFixed(2)+\' DH</div></div>\').join("");t.textContent=d.total.toFixed(2)+" DH";}function tick(){const n=new Date();document.getElementById("clk").textContent=String(n.getHours()).padStart(2,"0")+":"+String(n.getMinutes()).padStart(2,"0")+":"+String(n.getSeconds()).padStart(2,"0");}setInterval(tick,1000);tick();<\/script></body></html>');this.win.document.close();toast('Écran client ouvert','success');}};

/* ==================== DigitalReceipt ==================== */
const DigitalReceipt={currentSale:null,show(sale){this.currentSale=sale;document.getElementById('qrSaleId').textContent='Ticket '+sale.id;document.getElementById('qrSaleTotal').textContent=money(sale.total);const url=this.buildURL(sale);this.renderQR(url);document.getElementById('digitalReceiptModal').classList.add('show');},buildURL(sale){return location.origin+location.pathname+'?receipt='+btoa(JSON.stringify({id:sale.id,t:sale.total}));},renderQR(text){const c=document.getElementById('qrContainer');c.innerHTML='<img src="https://api.qrserver.com/v1/create-qr-code/?size=180x180&data='+encodeURIComponent(text)+'" style="width:180px;height:180px;display:block" onerror="this.parentElement.innerHTML=\'<div style=&quot;padding:40px;color:#999;font-size:12px&quot;>QR indisponible</div>\'">';},shareWhatsApp(){const s=this.currentSale;if(!s)return;const store=getStoreInfo();const client=db.clients.find(c=>c.id===s.clientId);const url=this.buildURL(s);const text='🧾 *'+(store.name||'Zarouali POS')+'*\n\nTicket: '+s.id+'\nTotal: '+money(s.total)+'\n\n'+url;const phone=client?.phone?client.phone.replace(/\D/g,''):'';window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(text),'_blank');},copyLink(){const s=this.currentSale;if(!s)return;const url=this.buildURL(s);try{navigator.clipboard.writeText(url).then(()=>toast('Lien copié','success'));}catch(e){prompt('Copier:',url);}}};

