const LabelGenerator={selected:[],open(){this.selected=[];document.getElementById('labelSearch').value='';this.search('');document.getElementById('labelsModal').classList.add('show');},search(q){q=String(q||'').toLowerCase().trim();const box=document.getElementById('labelProductList');let list=db.products;if(q)list=list.filter(p=>p.name.toLowerCase().includes(q)||String(p.barcode).includes(q));list=list.slice(0,100);if(!list.length){box.innerHTML='<div style="padding:30px;text-align:center;color:var(--text-muted)">Aucun</div>';return;}box.innerHTML=list.map(p=>{const sel=this.selected.find(x=>x.id===p.id);return'<div style="display:grid;grid-template-columns:30px 1fr auto;gap:12px;padding:10px 14px;border-bottom:1px solid var(--border-subtle);align-items:center;cursor:pointer" onclick="LabelGenerator.toggle(\''+p.id+'\')"><input type="checkbox" '+(sel?'checked':'')+' style="accent-color:var(--brand-500);width:18px;height:18px"><div><div style="font-weight:600;font-size:13px">'+escapeHTML(p.name)+'</div><div style="font-size:11px;color:var(--text-muted);font-family:var(--font-mono)">'+(p.barcode||'—')+' · '+money(p.price)+'</div></div></div>';}).join('');},toggle(id){const idx=this.selected.findIndex(x=>x.id===id);if(idx>=0)this.selected.splice(idx,1);else this.selected.push({id,copies:1});this.search(document.getElementById('labelSearch').value);},preview(){if(!this.selected.length){toast('Sélectionnez','warn');return;}const copies=parseInt(document.getElementById('labelCopies').value)||1;const labels=[];for(const sel of this.selected){const p=db.products.find(x=>x.id===sel.id);if(!p)continue;for(let i=0;i<copies;i++)labels.push(p);}const prev=labels.slice(0,6);let box=document.getElementById('labelPreviewBox');if(!box){box=document.createElement('div');box.id='labelPreviewBox';document.querySelector('#labelsModal .modal-body').appendChild(box);}box.innerHTML='<div style="margin-top:14px"><div class="eyebrow" style="margin-bottom:8px">Aperçu ('+labels.length+')</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:16px;background:var(--bg-surface-2);border-radius:var(--r-md)">'+prev.map(p=>'<div style="background:#fff;border:1px dashed #ccc;border-radius:4px;padding:6px;text-align:center;font-size:10px;color:#000"><b style="display:block;font-size:11px;margin-bottom:2px">'+escapeHTML(p.name.substring(0,20))+'</b><div style="font-size:14px;font-weight:800">'+money(p.price)+'</div><svg viewBox="0 0 100 24" style="width:100%;height:24px">'+this.barcodeSVG(p.barcode||p.id)+'</svg></div>').join('')+'</div></div>';},print(){if(!this.selected.length){toast('Sélectionnez','warn');return;}const copies=parseInt(document.getElementById('labelCopies').value)||1;const labels=[];for(const sel of this.selected){const p=db.products.find(x=>x.id===sel.id);if(!p)continue;for(let i=0;i<copies;i++)labels.push(p);}let h='<div style="background:white;color:black"><div style="display:flex;flex-wrap:wrap;gap:2mm;padding:5mm">';for(const p of labels){h+='<div style="width:50mm;height:30mm;border:1px solid #ccc;padding:2mm;text-align:center;box-sizing:border-box;display:flex;flex-direction:column;justify-content:space-between"><div style="font-size:9px;font-weight:bold">'+escapeHTML(p.name.substring(0,25))+'</div><div style="font-size:14px;font-weight:900">'+money(p.price)+'</div><svg viewBox="0 0 100 20" style="width:100%;height:8mm">'+this.barcodeSVG(p.barcode||p.id)+'</svg></div>';}h+='</div></div>';const pa=document.getElementById('printArea');pa.innerHTML=h;setTimeout(()=>{window.print();pa.innerHTML='';},300);},barcodeSVG(code){const s=String(code||'00000000');let bars='';let x=0;const seed=s.split('').reduce((a,c)=>a+c.charCodeAt(0),0);for(let i=0;i<s.length;i++){const c=s.charCodeAt(i);const w1=1+((c*7+seed)%3);const w2=1+((c*11+seed)%3);bars+='<rect x="'+x+'" y="0" width="'+w1+'" height="24" fill="black"/>';x+=w1+w2;bars+='<rect x="'+x+'" y="0" width="'+w2+'" height="24" fill="white"/>';x+=w1;}return'<rect width="'+x+'" height="24" fill="white"/>'+bars;}};

