const AdvancedReports={range:'today',open(){this.render();document.getElementById('reportsModal').classList.add('show');},setRange(r){this.range=r;document.querySelectorAll('.alerts-tab[data-range]').forEach(b=>b.classList.toggle('active',b.dataset.range===r));this.render();},getRangeSales(){const now=new Date();let from=new Date();if(this.range==='today')from.setHours(0,0,0,0);else if(this.range==='week')from.setDate(now.getDate()-7);else if(this.range==='month')from.setDate(now.getDate()-30);else if(this.range==='year')from.setFullYear(now.getFullYear()-1);return db.sales.filter(s=>new Date(s.date)>=from);},render(){const sales=this.getRangeSales();const ca=sales.reduce((s,x)=>s+x.total,0);const cost=sales.reduce((s,x)=>s+(x.cost||0),0);const tickets=sales.length;const avg=tickets?ca/tickets:0;const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v;};set('rptCA',money(ca));set('rptProfit',money(ca-cost));set('rptTickets',tickets);set('rptAvg',money(avg));this.drawChart(sales);const ps={};sales.forEach(s=>(s.items||[]).forEach(it=>{if(!ps[it.id])ps[it.id]={qty:0,ca:0};ps[it.id].qty+=it.qty;ps[it.id].ca+=it.price*it.qty;}));const sorted=Object.entries(ps).sort((a,b)=>b[1].ca-a[1].ca).slice(0,5);const max=sorted.length?sorted[0][1].ca:1;const tp=document.getElementById('rptTopProducts');if(tp)tp.innerHTML=sorted.length?sorted.map(([id,st])=>{const p=db.products.find(x=>x.id===id);const pct=(st.ca/max)*100;return'<div style="margin-bottom:10px"><div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px"><span>'+escapeHTML(p?p.name:id)+'</span><span class="mono">'+money(st.ca)+'</span></div><div class="credit-bar-track"><div class="credit-bar-fill" style="width:'+pct+'%"></div></div></div>';}).join(''):'<div style="color:var(--text-muted);text-align:center;padding:20px">Vide</div>';},drawChart(sales){const canvas=document.getElementById('rptChart');if(!canvas)return;const dpr=window.devicePixelRatio||1;const rect=canvas.getBoundingClientRect();canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const W=rect.width,H=rect.height;ctx.clearRect(0,0,W,H);const byDay={};sales.forEach(s=>{const d=localDateISO(new Date(s.date));byDay[d]=(byDay[d]||0)+s.total;});const days=Object.keys(byDay).sort();if(!days.length){ctx.fillStyle='#999';ctx.font='13px Inter';ctx.textAlign='center';ctx.fillText('Aucune donnée',W/2,H/2);return;}const pad={l:50,r:20,t:20,b:34};const cw=W-pad.l-pad.r,ch=H-pad.t-pad.b;const maxV=Math.max(...days.map(d=>byDay[d]),1);const isDark=document.documentElement.getAttribute('data-theme')==='dark';const textC=isDark?'#9aa393':'#5f6b52';const gridC=isDark?'#2c3129':'#e0e5d5';ctx.strokeStyle=gridC;ctx.lineWidth=1;ctx.font='11px Inter';ctx.fillStyle=textC;ctx.textAlign='end';for(let i=0;i<=4;i++){const y=pad.t+(ch/4)*i;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(W-pad.r,y);ctx.stroke();ctx.fillText((maxV*(1-i/4)).toFixed(0),pad.l-8,y+4);}const stepX=days.length>1?cw/(days.length-1):0;const points=days.map((d,i)=>({x:pad.l+i*stepX,y:pad.t+ch-(byDay[d]/maxV)*ch}));ctx.beginPath();ctx.moveTo(points[0].x,pad.t+ch);points.forEach(p=>ctx.lineTo(p.x,p.y));ctx.lineTo(points[points.length-1].x,pad.t+ch);ctx.closePath();const grad=ctx.createLinearGradient(0,pad.t,0,pad.t+ch);grad.addColorStop(0,'rgba(124,179,66,.35)');grad.addColorStop(1,'rgba(124,179,66,.02)');ctx.fillStyle=grad;ctx.fill();ctx.beginPath();points.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));ctx.strokeStyle='#7CB342';ctx.lineWidth=2.5;ctx.stroke();points.forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,3.5,0,Math.PI*2);ctx.fillStyle='#7CB342';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();});ctx.fillStyle=textC;ctx.textAlign='center';ctx.font='10px Inter';const stepLabel=Math.max(1,Math.ceil(days.length/5));days.forEach((d,i)=>{if(i%stepLabel===0||i===days.length-1){const x=pad.l+i*stepX;const dd=new Date(d);ctx.fillText(dd.getDate()+'/'+(dd.getMonth()+1),x,H-10);}});}};

