const Purchases={orders:[],currentItems:[],STORAGE_KEY:'zarouali_purchases',init(){try{const s=JSON.parse(localStorage.getItem(this.STORAGE_KEY)||'[]');if(Array.isArray(s))this.orders=s;}catch(e){}this.render();},openOrderModal(){this.currentItems=[];document.getElementById('editPurchaseId').value='';const sel=document.getElementById('purchaseSupplier');sel.innerHTML='<option value="">— Sélectionner —</option>'+(db.suppliers||[]).map(s=>'<option value="'+s.id+'">'+escapeHTML(s.name)+'</option>').join('');const d=new Date();d.setDate(d.getDate()+7);document.getElementById('purchaseDeliveryDate').value=d.toISOString().slice(0,10);this.addItem();document.getElementById('purchaseOrderModal').classList.add('show');},addItem(){this.currentItems.push({productId:'',qty:1,unitPrice:0});this.renderItems();},removeItem(i){this.currentItems.splice(i,1);if(!this.currentItems.length)this.addItem();this.renderItems();},setItemProduct(i,id){this.currentItems[i].productId=id;const p=db.products.find(x=>x.id===id);if(p)this.currentItems[i].unitPrice=p.purchasePrice||0;this.renderItems();},setItemField(i,field,value){this.currentItems[i][field]=field==='qty'?parseInt(value)||0:parseFloat(value)||0;this.renderItems();},renderItems(){const box=document.getElementById('purchaseItemsList');if(!box)return;box.innerHTML=this.currentItems.map((it,i)=>{const opts='<option value="">— Produit —</option>'+(db.products||[]).map(p=>'<option value="'+p.id+'" '+(p.id===it.productId?'selected':'')+'>'+escapeHTML(p.name)+'</option>').join('');const total=it.qty*it.unitPrice;return'<div class="purchase-item"><select onchange="Purchases.setItemProduct('+i+',this.value)">'+opts+'</select><input type="number" min="1" value="'+it.qty+'" onchange="Purchases.setItemField('+i+',\'qty\',this.value)"><input type="number" min="0" step="0.01" value="'+it.unitPrice.toFixed(2)+'" onchange="Purchases.setItemField('+i+',\'unitPrice\',this.value)"><div class="line-total">'+money(total)+'</div><button class="remove-line" onclick="Purchases.removeItem('+i+')">×</button></div>';}).join('');const ti=this.currentItems.reduce((s,it)=>s+it.qty,0);const t=this.currentItems.reduce((s,it)=>s+it.qty*it.unitPrice,0);document.getElementById('purchaseTotalItems').textContent=ti;document.getElementById('purchaseTotal').textContent=money(t);},saveOrder(){const sid=document.getElementById('purchaseSupplier').value;if(!sid){toast('Sélectionnez fournisseur','error');return;}const items=this.currentItems.filter(it=>it.productId&&it.qty>0);if(!items.length){toast('Ajoutez articles','error');return;}const total=items.reduce((s,it)=>s+it.qty*it.unitPrice,0);const order={id:'PO'+Date.now().toString(36).toUpperCase(),supplierId:sid,items:items.map(it=>({...it})),total,deliveryDate:document.getElementById('purchaseDeliveryDate').value,status:'pending',createdAt:Date.now()};this.orders.unshift(order);this.save();closeModal('purchaseOrderModal');this.render();toast('Commande créée: '+order.id,'success');},receive(id){const o=this.orders.find(x=>x.id===id);if(!o||o.status==='received')return;if(!confirm('Réceptionner ?'))return;for(const it of o.items){const p=db.products.find(x=>x.id===it.productId);if(p){p.stock+=it.qty;p.purchasePrice=it.unitPrice;}}o.status='received';o.receivedAt=Date.now();const s=db.suppliers.find(x=>x.id===o.supplierId);if(s)s.balance=(s.balance||0)+o.total;saveDB();this.save();this.render();renderAll();toast('Commande réceptionnée','success');},render(){const box=document.getElementById('purchasesAdmin');if(!box)return;if(!this.orders.length){box.innerHTML='<tr><td colspan="7" style="text-align:center;color:var(--text-muted);padding:40px">Aucune commande</td></tr>';return;}box.innerHTML=this.orders.map(o=>{const sup=db.suppliers.find(s=>s.id===o.supplierId);const ic=o.items.reduce((s,it)=>s+it.qty,0);return'<tr><td><strong class="mono">'+o.id+'</strong></td><td>'+new Date(o.createdAt).toLocaleDateString('fr-FR')+'</td><td>'+escapeHTML(sup?sup.name:'—')+'</td><td class="mono">'+ic+'</td><td class="mono">'+money(o.total)+'</td><td>'+(o.status==='received'?'<span style="color:var(--success-500);font-weight:800;font-size:12px">✓ Reçue</span>':'<span style="color:var(--warn-500);font-weight:800;font-size:12px">⏳ Attente</span>')+'</td><td>'+(o.status==='pending'?'<button class="btn btn-secondary btn-sm" onclick="Purchases.receive(\''+o.id+'\')" style="color:var(--success-500)">✓ Réceptionner</button>':'—')+'</td></tr>';}).join('');},save(){try{localStorage.setItem(this.STORAGE_KEY,JSON.stringify(this.orders));}catch(e){}}};

