const PriceLists={enabled:true,discounts:{standard:0,wholesale:-10,vip:-20,reseller:-15},STORAGE_KEY:'zarouali_price_lists',init(){try{const s=JSON.parse(localStorage.getItem(this.STORAGE_KEY)||'{}');if(s.enabled!==undefined)this.enabled=s.enabled;if(s.discounts)Object.assign(this.discounts,s.discounts);}catch(e){}},setEnabled(v){this.enabled=!!v;this.save();},save(){this.discounts={standard:parseFloat(document.getElementById('priceStandard').value)||0,wholesale:parseFloat(document.getElementById('priceWholesale').value)||0,vip:parseFloat(document.getElementById('priceVip').value)||0,reseller:parseFloat(document.getElementById('priceReseller').value)||0};this.saveToStorage();toast('Enregistré','success');},saveToStorage(){try{localStorage.setItem(this.STORAGE_KEY,JSON.stringify({enabled:this.enabled,discounts:this.discounts}));}catch(e){}},getPrice(product,clientId){if(!this.enabled)return product.price;let tier='standard';if(clientId){const c=db.clients.find(x=>x.id===clientId);if(c&&c.tier)tier=c.tier;}const pct=this.discounts[tier]||0;return Math.max(0,product.price*(1+pct/100));}};

