/* ==================== INIT ==================== */

async function loadImportedCatalog(file){
  if(!file) return false;
  if(typeof JSZip==="undefined") throw new Error("JSZip not loaded");
  if(typeof initSqlJs==="undefined") throw new Error("sql.js not loaded");

  const zip=await JSZip.loadAsync(file);
  const dbFile=zip.file("catalog.db");
  if(!dbFile) throw new Error("catalog.db introuvable dans le ZIP");

  const bytes=await dbFile.async("uint8array");
  const SQL=await initSqlJs({
    locateFile:()=> "./vendor/sql-wasm.wasm"
  });
  const catalogDB=new SQL.Database(bytes);

  const result=catalogDB.exec(
    "SELECT id,name,category,barcode,price,purchasePrice,stock,minStock,image FROM products"
  );

  if(!result.length) throw new Error("Table products vide ou absente");

  const cols=result[0].columns;
  const rows=result[0].values;

  db.products=rows.map(r=>{
    const p={};
    cols.forEach((c,i)=>p[c]=r[i]??"");
    p.price=Number(p.price)||0;
    p.purchasePrice=Number(p.purchasePrice)||p.price*0.65;
    p.stock=Number(p.stock)||0;
    p.minStock=Number(p.minStock)||5;
    return p;
  });

  saveDB();
  renderAll();
  updateStorePreview();

  localStorage.setItem("zarouali_catalog_imported","1");
  localStorage.setItem("zarouali_catalog_count",String(db.products.length));

  return true;
}

async function init(){
  currentLanguage=localStorage.getItem(LANG_KEY)||'fr';
  document.documentElement.dir=currentLanguage==='ar'?'rtl':'ltr';
  loadTheme();
  renderMenu();
  renderMainContent();
  startDigitalClock();

  ScannerHID.init();
  ScannerBLE.init();
  ScanStats.init();
  ScanHistory.init();
  ParkedSales.init();
  ShiftManagement.init();
  StockAlerts.init();
  Loyalty.init();
  AuditLog.init();
  CustomerDisplay.init();
  CommandPalette.init();
  Purchases.init();
  PriceLists.init();
  Suppliers.populateProductSelect();

  const store=localStorage.getItem(STORE_KEY);
  if(store){try{const s=JSON.parse(store);if(s.name){db.settings.storeName=s.name;}}catch(e){}}
  const saved=localStorage.getItem(DB_KEY);
  let cloud=null;
  if(window.fsLoadDB){try{cloud=await window.fsLoadDB();}catch(e){}}
  if(cloud){db=cloud;localStorage.setItem(DB_KEY,JSON.stringify(db));}
  else if(saved){try{db=JSON.parse(saved);}catch(e){createDefaultDB();}}
  else createDefaultDB();

  if(!db.products)db.products=[];
  if(!db.clients)db.clients=[];
  if(!db.suppliers)db.suppliers=[];
  if(!db.purchases)db.purchases=[];
  if(!db.returns)db.returns=[];
  if(!db.cashiers||!db.cashiers.length)db.cashiers=[{id:"C1",name:"Caissière 1"},{id:"C2",name:"Caissière 2"}];
  if(!localStorage.getItem(PASSWORD_KEY))localStorage.setItem(PASSWORD_KEY,"1234");
  if(!localStorage.getItem(LOGIN_KEY))localStorage.setItem(LOGIN_KEY,JSON.stringify({username:"admin",password:"1234"}));
  db.products=db.products.map(p=>{if(p.purchasePrice===undefined)p.purchasePrice=Number(p.price)*0.65;if(p.minStock===undefined)p.minStock=5;if(p.image===undefined)p.image="";if(p.expirationDate===undefined)p.expirationDate="";if(p.saleType===undefined)p.saleType="unit";return p;});
  db.clients.forEach(c=>{if(c.debt===undefined)c.debt=0;if(c.totalPurchases===undefined)c.totalPurchases=0;if(c.tier===undefined)c.tier="standard";if(c.points===undefined)c.points=0;});

  // ===== ZAROUALI CATALOG : SQLite/ZIP =====
  // No products are bundled in the GitHub project.
  // The administrator imports Zarouali_Catalog_FINAL.zip from the app.
  try{
    await loadImportedCatalog();
  }catch(e){
    console.warn("Catalog not imported yet:",e);
  }

  saveDB();renderAll();
  updateStorePreview();

  if(window.fsListen){window.fsListen(remote=>{db=remote;localStorage.setItem(DB_KEY,JSON.stringify(db));renderAll();});}

  const d=document.getElementById("historyDate");
  if(d)d.value=localDateISO();

  resetInactivityTimer();
  ["click","touchstart","keydown","mousemove"].forEach(e=>document.addEventListener(e,resetInactivityTimer));

  document.addEventListener("keydown",e=>{
    if(e.key==="F1"){e.preventDefault();showKeyboardHelp();}
    if(e.key==="F2"){e.preventDefault();document.getElementById("search")?.focus();}
    if(e.key==="Escape"){closeMenu();document.querySelectorAll(".modal.show,.scanner-modal.show").forEach(m=>m.classList.remove("show"));}
    if(e.key==="F4"){e.preventDefault();cart=[];renderCart();toast('Nouvelle vente','info');}
    if(e.key==="F5"){e.preventDefault();renderAll();toast(t('refreshed'),'success');}
    if(e.ctrlKey&&e.key.toLowerCase()==="b"){e.preventDefault();openScanner();}
    if(e.ctrlKey&&e.key==="Enter"){e.preventDefault();completeSale();}
    if(e.ctrlKey&&(e.key==="Delete"||e.key==="Backspace")){e.preventDefault();clearCart();}
    if(e.ctrlKey&&e.key.toLowerCase()==="h"){e.preventDefault();ScanHistory.open();}
  });

  const header=document.querySelector('.header');
  window.addEventListener('scroll',()=>{if(header)header.classList.toggle('scrolled',window.scrollY>8);},{passive:true});

  const si=document.getElementById("search");
  if(si){
    let timer=null;
    si.addEventListener("input",function(){
      clearTimeout(timer);
      timer=setTimeout(()=>{
        const v=this.value.trim();
        if(!v){renderProducts();timer=null;return;}
        if(/^\d{8,}$/.test(v)){
          const p=db.products.find(x=>String(x.barcode)===v);
          if(p){addToCart(p.id);playBeep();this.value="";toast('✓ '+p.name,'success');}
          else{playErrorBeep();openProductModal(null,v);this.value="";toast('Code inconnu','warn');}
        }else renderProducts();
        timer=null;
      },300);
    });
  }

  const ss=document.getElementById("screensaver");
  if(ss){
    ss.addEventListener("click",function(){this.classList.remove("show");resetInactivityTimer();});
    ss.addEventListener("touchstart",function(){this.classList.remove("show");resetInactivityTimer();});
  }

  const ld=localStorage.getItem(LOGIN_KEY);
  if(ld){try{const d=JSON.parse(ld);if(d.username)document.getElementById("loginUser").value=d.username;}catch(e){}}
}

document.addEventListener("DOMContentLoaded",init);
